import java.util.*;

class Solution {
    public int[] smallestSufficientTeam(String[] req_skills, List<List<String>> people) {
        int m = req_skills.length;
        int n = people.size();
        Map<String, Integer> skillIndex = new HashMap<>();
        for (int i = 0; i < m; i++) {
            skillIndex.put(req_skills[i], i);
        }

        int[] personMask = new int[n];
        for (int i = 0; i < n; i++) {
            for (String skill : people.get(i)) {
                personMask[i] |= 1 << skillIndex.get(skill);
            }
        }

        int full = (1 << m) - 1;
        int[] size = new int[full + 1];
        long[] team = new long[full + 1];
        Arrays.fill(size, n + 1);
        size[0] = 0;

        for (int person = 0; person < n; person++) {
            if (personMask[person] == 0) {
                continue;
            }
            for (int mask = 0; mask <= full; mask++) {
                if (size[mask] == n + 1) {
                    continue;
                }
                int next = mask | personMask[person];
                if (size[mask] + 1 < size[next]) {
                    size[next] = size[mask] + 1;
                    team[next] = team[mask] | (1L << person);
                }
            }
        }

        return toArray(team[full], n);
    }

    private int[] toArray(long teamMask, int n) {
        int[] answer = new int[Long.bitCount(teamMask)];
        int index = 0;
        for (int person = 0; person < n; person++) {
            if ((teamMask & (1L << person)) != 0) {
                answer[index++] = person;
            }
        }
        return answer;
    }
}

