import java.util.*;

class Solution {
    private int fullMask;
    private int[] personMasks;
    private List<Integer>[] peopleBySkill;
    private long[] memo;
    private boolean[] seen;

    public int[] smallestSufficientTeam(String[] req_skills, List<List<String>> people) {
        int m = req_skills.length;
        int n = people.size();
        Map<String, Integer> skillIndex = new HashMap<>();
        for (int i = 0; i < m; i++) {
            skillIndex.put(req_skills[i], i);
        }

        personMasks = new int[n];
        peopleBySkill = new ArrayList[m];
        for (int skill = 0; skill < m; skill++) {
            peopleBySkill[skill] = new ArrayList<>();
        }
        for (int person = 0; person < n; person++) {
            for (String skill : people.get(person)) {
                int bit = skillIndex.get(skill);
                personMasks[person] |= 1 << bit;
            }
            for (int skill = 0; skill < m; skill++) {
                if ((personMasks[person] & (1 << skill)) != 0) {
                    peopleBySkill[skill].add(person);
                }
            }
        }

        fullMask = (1 << m) - 1;
        memo = new long[1 << m];
        seen = new boolean[1 << m];
        long teamMask = dfs(0);
        return toArray(teamMask, n);
    }

    private long dfs(int mask) {
        if (mask == fullMask) {
            return 0L;
        }
        if (seen[mask]) {
            return memo[mask];
        }

        int missingSkill = Integer.numberOfTrailingZeros(fullMask ^ mask);
        long best = Long.MAX_VALUE;
        for (int person : peopleBySkill[missingSkill]) {
            int next = mask | personMasks[person];
            if (next == mask) {
                continue;
            }
            long suffix = dfs(next);
            if (suffix == Long.MAX_VALUE) {
                continue;
            }
            long candidate = suffix | (1L << person);
            if (Long.bitCount(candidate) < Long.bitCount(best)) {
                best = candidate;
            }
        }

        seen[mask] = true;
        memo[mask] = best;
        return best;
    }

    private int[] toArray(long teamMask, int n) {
        int[] answer = new int[Long.bitCount(teamMask)];
        int index = 0;
        for (int person = 0; person < n; person++) {
            if ((teamMask & (1L << person)) != 0) {
                answer[index++] = person;
            }
        }
        return answer;
    }
}

