class Solution {
    public int[] smallestSufficientTeam(String[] req_skills, List<List<String>> people) {
        int m = req_skills.length;
        int n = people.size();
        Map<String, Integer> skillIndex = new HashMap<>();
        for (int i = 0; i < m; i++) {
            skillIndex.put(req_skills[i], i);
        }

        int[] personMask = new int[n];
        for (int person = 0; person < n; person++) {
            for (String skill : people.get(person)) {
                personMask[person] |= 1 << skillIndex.get(skill);
            }
        }

        int full = (1 << m) - 1;
        int[] previousMask = new int[full + 1];
        int[] addedPerson = new int[full + 1];
        Arrays.fill(previousMask, -1);
        Arrays.fill(addedPerson, -1);
        ArrayDeque<Integer> queue = new ArrayDeque<>();
        previousMask[0] = 0;
        queue.add(0);

        while (!queue.isEmpty() && previousMask[full] == -1) {
            int mask = queue.remove();
            for (int person = 0; person < n; person++) {
                int next = mask | personMask[person];
                if (next != mask && previousMask[next] == -1) {
                    previousMask[next] = mask;
                    addedPerson[next] = person;
                    if (next == full) {
                        break;
                    }
                    queue.add(next);
                }
            }
        }

        List<Integer> team = new ArrayList<>();
        for (int mask = full; mask != 0; mask = previousMask[mask]) {
            team.add(addedPerson[mask]);
        }
        int[] answer = new int[team.size()];
        for (int i = 0; i < team.size(); i++) {
            answer[i] = team.get(i);
        }
        return answer;
    }
}

import java.util.*;

class Solution {
    private int fullMask;
    private int[] masks;
    private int[] originalIndex;
    private List<Integer>[] peopleBySkill;
    private List<Integer> best = new ArrayList<>();

    public int[] smallestSufficientTeam(String[] req_skills, List<List<String>> people) {
        int m = req_skills.length;
        Map<String, Integer> skillIndex = new HashMap<>();
        for (int i = 0; i < m; i++) {
            skillIndex.put(req_skills[i], i);
        }

        int n = people.size();
        int[] rawMask = new int[n];
        for (int person = 0; person < n; person++) {
            for (String skill : people.get(person)) {
                rawMask[person] |= 1 << skillIndex.get(skill);
            }
        }

        List<Integer> keptMasks = new ArrayList<>();
        List<Integer> keptOriginal = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (rawMask[i] == 0) {
                continue;
            }
            boolean dominated = false;
            for (int j = 0; j < n; j++) {
                if (i == j || rawMask[j] == 0) {
                    continue;
                }
                boolean subset = (rawMask[i] | rawMask[j]) == rawMask[j];
                boolean strictlyBetter = rawMask[i] != rawMask[j] || j < i;
                if (subset && strictlyBetter) {
                    dominated = true;
                    break;
                }
            }
            if (!dominated) {
                keptMasks.add(rawMask[i]);
                keptOriginal.add(i);
            }
        }

        masks = new int[keptMasks.size()];
        originalIndex = new int[keptOriginal.size()];
        for (int i = 0; i < keptMasks.size(); i++) {
            masks[i] = keptMasks.get(i);
            originalIndex[i] = keptOriginal.get(i);
        }

        fullMask = (1 << m) - 1;
        peopleBySkill = new ArrayList[m];
        for (int skill = 0; skill < m; skill++) {
            peopleBySkill[skill] = new ArrayList<>();
        }
        for (int person = 0; person < masks.length; person++) {
            for (int skill = 0; skill < m; skill++) {
                if ((masks[person] & (1 << skill)) != 0) {
                    peopleBySkill[skill].add(person);
                }
            }
        }

        best = new ArrayList<>();
        for (int i = 0; i < people.size(); i++) {
            best.add(i);
        }
        search(0, new ArrayList<>());

        int[] answer = new int[best.size()];
        for (int i = 0; i < best.size(); i++) {
            answer[i] = best.get(i);
        }
        return answer;
    }

    private void search(int mask, List<Integer> team) {
        if (team.size() >= best.size()) {
            return;
        }
        if (mask == fullMask) {
            best = new ArrayList<>(team);
            return;
        }

        int skill = rarestMissingSkill(mask);
        for (int person : peopleBySkill[skill]) {
            int next = mask | masks[person];
            if (next == mask) {
                continue;
            }
            team.add(originalIndex[person]);
            search(next, team);
            team.remove(team.size() - 1);
        }
    }

    private int rarestMissingSkill(int mask) {
        int bestSkill = -1;
        int bestCount = Integer.MAX_VALUE;
        for (int skill = 0; skill < peopleBySkill.length; skill++) {
            if ((mask & (1 << skill)) != 0) {
                continue;
            }
            int count = 0;
            for (int person : peopleBySkill[skill]) {
                if ((mask | masks[person]) != mask) {
                    count++;
                }
            }
            if (count < bestCount) {
                bestCount = count;
                bestSkill = skill;
            }
        }
        return bestSkill;
    }
}
